mkdir -p /tmp/chand && cd /tmp/chand && cat > shell.mjs <<'EOF'
import { Grid } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const g = new Grid([26, 26, 34]);
for (let x=0;x<26;x++) for (let z=0;z<34;z++) g.set(x,0,z,"grass_block");
const box=(a,b,m)=>{for(let x=a[0];x<=b[0];x++)for(let y=a[1];y<=b[1];y++)for(let z=a[2];z<=b[2];z++){const e=x==a[0]||x==b[0]||z==a[2]||z==b[2]||y==a[1];if(e)g.set(x,y,z,m);}};
box([5,1,8],[17,5,17],"bricks");
box([5,6,7],[17,10,17],"calcite");
box([5,1,18],[13,6,27],"bricks");
g.save(process.argv[2]);
EOF
node shell.mjs shell.nbt && MCD="node /Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs"
cat > main.json <<'EOF'
{"preset":"cottage","material":"slate","ridgeAxis":"x","front":"n","footprint":[[5,7,17,17],[9,7,13,12]],"y":11,"gable":"calcite","chimneys":[]}
EOF
$MCD roof shell.nbt main.nbt --spec main.json 2>&1 | tail -25
